-- Geo reference data (countries / states / cities) from
-- https://github.com/dr5hn/countries-states-cities-database  (release v3.2-export.5)
-- Lean build: postcodes table excluded; cities.translations column excluded.
-- Integer IDs are the upstream canonical IDs (same as the countrystatecity.in API);
-- they are intentionally NOT app-generated UUIDs.

CREATE SCHEMA IF NOT EXISTS geo;

CREATE TABLE geo.regions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name character varying(100) NOT NULL,
    translations text,
    created_at timestamp without time zone,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    flag smallint DEFAULT 1 NOT NULL,
    "wikiDataId" character varying(255)
);

CREATE TABLE geo.subregions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name character varying(100) NOT NULL,
    translations text,
    region_id bigint NOT NULL REFERENCES geo.regions(id),
    created_at timestamp without time zone,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    flag smallint DEFAULT 1 NOT NULL,
    "wikiDataId" character varying(255)
);

CREATE TABLE geo.countries (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name character varying(100) NOT NULL,
    iso3 character(3),
    numeric_code character(3),
    iso2 character(2),
    phonecode character varying(255),
    capital character varying(255),
    currency character varying(255),
    currency_name character varying(255),
    currency_symbol character varying(255),
    tld character varying(255),
    native character varying(255),
    population bigint,
    gdp bigint,
    region character varying(255),
    region_id bigint REFERENCES geo.regions(id),
    subregion character varying(255),
    subregion_id bigint REFERENCES geo.subregions(id),
    nationality character varying(255),
    area_sq_km double precision,
    postal_code_format character varying(255),
    postal_code_regex character varying(255),
    timezones text,
    translations text,
    latitude numeric(10,8),
    longitude numeric(11,8),
    emoji character varying(191),
    "emojiU" character varying(191),
    created_at timestamp without time zone,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    flag smallint DEFAULT 1 NOT NULL,
    "wikiDataId" character varying(255)
);

CREATE TABLE geo.states (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name character varying(255) NOT NULL,
    country_id bigint NOT NULL REFERENCES geo.countries(id),
    country_code character(2) NOT NULL,
    fips_code character varying(255),
    iso2 character varying(255),
    iso3166_2 character varying(10),
    type character varying(191),
    level integer,
    parent_id bigint,
    native character varying(255),
    latitude numeric(10,8),
    longitude numeric(11,8),
    timezone character varying(255),
    translations text,
    created_at timestamp without time zone,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    flag smallint DEFAULT 1 NOT NULL,
    "wikiDataId" character varying(255),
    population character varying(255)
);

CREATE TABLE geo.cities (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name character varying(255) NOT NULL,
    state_id bigint NOT NULL REFERENCES geo.states(id),
    state_code character varying(255) NOT NULL,
    country_id bigint NOT NULL REFERENCES geo.countries(id),
    country_code character(2) NOT NULL,
    type character varying(191),
    level integer,
    parent_id bigint,
    latitude numeric(10,8) NOT NULL,
    longitude numeric(11,8) NOT NULL,
    native character varying(255),
    population bigint,
    timezone character varying(255),
    created_at timestamp without time zone DEFAULT '2014-01-01 12:01:01'::timestamp without time zone NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    flag smallint DEFAULT 1 NOT NULL,
    "wikiDataId" character varying(255)
);

CREATE INDEX countries_region_id_idx ON geo.countries USING btree (region_id);
CREATE INDEX countries_subregion_id_idx ON geo.countries USING btree (subregion_id);
CREATE INDEX subregions_region_id_idx ON geo.subregions USING btree (region_id);
CREATE INDEX states_country_id_idx ON geo.states USING btree (country_id);
CREATE INDEX cities_country_id_idx ON geo.cities USING btree (country_id);
CREATE INDEX cities_state_id_idx ON geo.cities USING btree (state_id);

-- regions: 6 rows

-- subregions: 22 rows

-- countries: 250 rows

-- states: 5308 rows

-- cities: 152967 rows


-- Advance identity sequences past the inserted explicit ids.
SELECT setval(pg_get_serial_sequence('geo.regions',   'id'), (SELECT COALESCE(MAX(id), 1) FROM geo.regions));
SELECT setval(pg_get_serial_sequence('geo.subregions','id'), (SELECT COALESCE(MAX(id), 1) FROM geo.subregions));
SELECT setval(pg_get_serial_sequence('geo.countries', 'id'), (SELECT COALESCE(MAX(id), 1) FROM geo.countries));
SELECT setval(pg_get_serial_sequence('geo.states',    'id'), (SELECT COALESCE(MAX(id), 1) FROM geo.states));
SELECT setval(pg_get_serial_sequence('geo.cities',    'id'), (SELECT COALESCE(MAX(id), 1) FROM geo.cities));
